def jac_action32(y,lam):
 y=np.asarray(y,dtype=np.float32);grad=centered_gradient(y,np.float32);P=np.zeros((r.N,r.N),dtype=np.float32);C=np.zeros_like(P);steps=np.zeros(r.N,dtype=np.float32)
 for b in r.blocks:
  ii=b['indices'];n=len(ii);step=np.float32(b['step']);z=y[ii]-step*grad[ii];domain=b['original']['domain'];Dz=np.eye(n,dtype=np.float32);Dc=np.zeros(n,dtype=np.float32)
  cap=np.float32(b['original']['cap']) if b['normal_indices'] is None else np.maximum(np.float32(0),np.asarray(b['original']['weights'],dtype=np.float32)@y[b['normal_indices']])
  if domain=='positive':Dz=np.diag((z>0).astype(np.float32))
  elif domain=='box':Dz=np.diag((abs(z)<cap).astype(np.float32));Dc=np.where(abs(z)>=cap,np.sign(z),np.float32(0))
  elif domain=='ball':
   length=np.linalg.norm(z)
   if length>cap:
    u=z/length;Dz=(cap/length)*(np.eye(n,dtype=np.float32)-np.outer(u,u));Dc=u
  assert Dz.dtype==Dc.dtype==np.float32
  P[np.ix_(ii,ii)]=Dz;steps[ii]=step
  if b['normal_indices'] is not None and cap>0:C[np.ix_(ii,b['normal_indices'])]=np.outer(Dc,np.asarray(b['original']['weights'],dtype=np.float32))
 P=csr_matrix(P);C=csr_matrix(C)
 return lambda v:np.float32(1+lam)*v-P@(v-steps*Schur32(v))-C@v

