import json,hashlib,base64,zlib,tempfile,sys,numpy as np
p=Path(__file__).resolve().parent;bench=Path('experiments/gpu-physics/benchmarks');record=json.loads((bench/'2026-09-29-rain-centered-gradient32.json').read_text());deps={}
for dep in record['dependencies']:
 f=Path(dep['receipt']);assert hashlib.sha256(f.read_bytes()).hexdigest()==dep['sha256'];deps[f.stem]=json.loads(f.read_text())
parent=deps['2026-09-29-rain-coupled-reference'];pose=deps['2026-09-29-rain-reference-exact-pose'];sep=deps['2026-09-29-rain-reference-exact-separation']
def raw(r):
 data=zlib.decompress(base64.b64decode(r['data']));assert hashlib.sha256(data).hexdigest()==r['sha256'] and len(data)==r['uncompressed_bytes'];return data
with tempfile.TemporaryDirectory(prefix='corrected-reference-portable-') as tmp:
 base=Path(tmp);trace=base/parent['input_trace']['relative_path'];trace.parent.mkdir(parents=True);trace.write_bytes(raw(parent['input_trace']));folder=base/'rain-reference-exact-pose';(folder/'hip-probe').mkdir(parents=True);(folder/'hip-probe/trace.jsonl').write_bytes(raw(pose['witness_trace']));(folder/'model.py').write_text(pose['sources']['model.py']);(folder/'wave.py').write_text(parent['sources']['wave.py']);sys.path.insert(0,str(folder));import model as m
 normals={json.dumps(b['label'][1])+':'+str(b['label'][3]):b for b in m.blocks if b['label'][0]=='contact' and b['label'][2]=='normal'}
 for rec in sep['results']['result.json']['separations']:normals[json.dumps(rec['identity'])+':'+str(rec['point'])]['bias'][:]=rec['exact_bias']
 m.bias=np.concatenate([b['bias'] for b in m.blocks]);m.g=m.J@m.vfree+m.bias
 from wave import wave
 results={};velocities=[]
 for name in ['cold']:
  state=record['states'][name+'/solution.npz'];x=np.array(state['impulses']);v=m.vfree+m.M@m.J.T@x;velocities.append(v);natural=float(max(abs(m.residual(x))/(1+abs(x))));gradient=m.gradient_primal(x);assembled=m.H@x+m.g;agreement=float(max(abs(gradient-assembled)/(1+np.maximum(abs(gradient),abs(assembled)))));_,sweep=wave(x);feas=[]
  for b in m.blocks:
   val=x[b['sl']];cap=m.radius(b,x);domain=b['domain'];error=0
   if domain=='positive':error=max(0,-float(min(val)))
   elif domain=='box':error=max(0,float(max(abs(val)))-cap)/(1+cap)
   elif domain=='ball':error=max(0,float(np.linalg.norm(val))-cap)/(1+cap)
   feas.append(error)
  difference=float(max(abs(v-np.array(state['velocities']))));assert natural<=1e-8 and max(feas)<=1e-8 and agreement<=1e-9 and max(sweep['max_velocity_change'],sweep['max_impulse_change'])<=1e-5 and difference<=1e-12
  bad=x.copy();bad[0]+=.01;assert max(abs(m.residual(bad))/(1+abs(bad)))>1e-8
  results[name]=dict(natural=natural,feasibility=max(feas),primal_agreement=agreement,sweep=sweep,stored_velocity_difference=difference,corruption_rejected=True)
 result=dict(status='portable-numerical-reference-pass',arms=results,scope='NumPy-only reconstruction from hashed receipts in a temporary directory. No original artifact paths or optimizers; not GPU/physical qualification.')
(p/'portable-validation.json').write_text(json.dumps(result,indent=2));print(json.dumps(result,indent=2))
